function words(n){if(!Number.isSafeInteger(n)||n<0||n>99999999)throw Error('Unsupported number words');if(n<20)return ones[n];if(n<100)return tens[Math.floor(n/10)]+(n%10?'-'+ones[n%10]:'');for(const [v,label] of [[1000000,'million'],[1000,'thousand'],[100,'hundred']])if(n>=v)return words(Math.floor(n/v))+' '+label+(n%v?' '+words(n%v):'');}
