 b+=ln(60,Y(lo)+8,60,Y(hi)-8,{w:1.4})+ln(52,Y(lo),X(dates[dates.length-1])+14,Y(lo),{w:1.4})+tx(W/2,246,'April date',{size:12})+tx(18,110,'°F',{size:12});
