function figureDraw(type,A,B,label){const x1=60,x2=300,y=40;let s=ln(type==='line'?20:x1,y,type==='segment'?x2:340,y,{w:1.8,start:type==='line'?1:0,end:type==='segment'?0:1});s+=`<circle cx="${x1}" cy="${y}" r="4" fill="${INK}"/><circle cx="${x2}" cy="${y}" r="4" fill="${INK}"/>`+tx(x1,y-14,A,{italic:1,size:16})+tx(x2,y-14,B,{italic:1,size:16});return svg(s,label,360,60);}
