// A circle divided into d equal parts with the first k shaded, centred at (cx,cy).
function pie(cx,cy,r,d,k){let b='';for(let j=0;j<d;j++){const a0=2*Math.PI*j/d-Math.PI/2,a1=2*Math.PI*(j+1)/d-Math.PI/2;b+=`<path d="M${cx},${cy} L${(cx+r*Math.cos(a0)).toFixed(1)},${(cy+r*Math.sin(a0)).toFixed(1)} A${r},${r} 0 0 1 ${(cx+r*Math.cos(a1)).toFixed(1)},${(cy+r*Math.sin(a1)).toFixed(1)} Z" fill="${j<k?S.SHADE:'none'}" fill-opacity="0.55" stroke="${INK}" stroke-width="1.2"/>`;}return b;}
