 if(a.kind==='i4-frac-any'){const m=s.replace(/\s+/g,'').match(/^(\d+)\/(\d+)$/);return okv(!!m&&Number(m[2])>0&&Number(m[1])*a.d===a.n*Number(m[2]));}
 // A number with one of the accepted unit forms (or none): "68°F", "68 °F", "68 degrees", "68".
 if(a.kind==='i4-num-unit'){const r=s.trim().toLowerCase().replace(/[−–]/g,'-').replace(/(\d),(?=\d{3}\b)/g,'$1'),m=r.match(/^(-?\d+(?:\.\d+)?)\s*(.*)$/);if(!m)return fail;const u=m[2].trim().replace(/\.$/,'');return okv(Number(m[1])===a.v&&(u===''||a.units.map(x=>x.toLowerCase()).includes(u)));}
 // Batch I4-13
