  if(dm)ok=Math.round(Number(x)*a.d)===a.n&&dm[2].length<=3;else if(fm){const w=Number(fm[1]||0),p=Number(fm[2]),q=Number(fm[3]);ok=q>0&&(w*q+p)*a.d===a.n*q&&(!fm[1]||p<q);}
